import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("ReportServlet");
    private Connection dbConn;

    @Override
    public void init() throws ServletException {
        try {
            String url = System.getenv("DB_URL");
            String user = System.getenv("DB_USER");
            String pass = System.getenv("DB_PASS");
            dbConn = DriverManager.getConnection(url, user, pass);
            log.info("Database connection established to: " + url);
        } catch (SQLException e) {
            throw new ServletException("DB init failed", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String format = req.getParameter("format");

        // Validate report type against allowed values
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation using regex
        if (!isValidDate(startDate) || !isValidDate(endDate)) {
            resp.sendError(400, "Invalid date format. Use YYYY-MM-DD");
            return;
        }

        try {
            String query = buildReportQuery(reportType, startDate, endDate, department);
            log.fine("Executing report query for type: " + reportType);

            Statement stmt = dbConn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }
            rs.close();
            stmt.close();

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String start, String end, String dept) {
        String baseQuery;
        switch (type) {
            case "sales":
                baseQuery = "SELECT order_id, amount, customer, region FROM sales";
                break;
            case "inventory":
                baseQuery = "SELECT sku, quantity, warehouse, last_updated FROM inventory";
                break;
            case "payroll":
                baseQuery = "SELECT emp_id, department, gross_pay, period FROM payroll";
                break;
            default:
                baseQuery = "SELECT id, description, created_at FROM audit_log";
        }

        StringBuilder sb = new StringBuilder(baseQuery);
        sb.append(" WHERE created_at BETWEEN '" + start + "' AND '" + end + "'");

        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '" + dept + "'");
        }

        sb.append(" ORDER BY created_at DESC LIMIT 1000");
        return sb.toString();
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        return type.equals("sales") || type.equals("inventory") ||
               type.equals("payroll") || type.equals("audit");
    }

    private boolean isValidDate(String date) {
        if (date == null) return false;
        return date.matches("\\d{4}-\\d{2}-\\d{2}");
    }
}
